esbmc_test_source:
contract InvMutTest {
    C c;
    constructor() payable { c = new C{value: 1 ether}(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Inputs: guess hash to lock, amount to send to lockInGuess (must be 1 ether to succeed),
    // and an extra dummy boolean to allow exploration of different call sequences.
    function run(bytes32 guessHash, uint lockValue, bool callSettleBefore) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (lockValue)); require(lockValue <= 1000000000000000000000000000000);
        // We need enough balance to call lockInGuess with lockValue and possibly receive payments.
        require(address(this).balance >= lockValue);
        // Record contract C balance before any interactions
        uint beforeC = address(c).balance;

        // Optionally try settle first to observe behavior when no guess is set; we allow it to revert.
        bool settleRevertedBefore;
        c.settle(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            settleRevertedBefore = true;
        } else {
            settleRevertedBefore = false;
        }

        // Attempt to lock in a guess; this may revert (e.g., wrong value or already set), capture that.
        bool lockReverted;
        c.lockInGuess{value: lockValue}(guessHash); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            lockReverted = true;
        } else {
            lockReverted = false;
        }

        // After lock attempt, record intermediate balance
        uint midC = address(c).balance;

        // Attempt to call settle afterwards; it may revert depending on block number or stored state.
        bool settleRevertedAfter;
        c.settle(); bool __rev2 = __ESBMC_reverted(); if (__rev2) {
            settleRevertedAfter = true;
        } else {
            settleRevertedAfter = false;
        }

        // Final observed balance
        uint afterC = address(c).balance;

        // General rule asserted:
        // If lockInGuess succeeded then final balance of c is either unchanged or decreased by exactly 2 ether (payout).
        // If lockInGuess reverted then c's balance did not increase as a result of this transaction (no unexpected gain).
        assert(
            (
                // Case A: lock failed -> c.balance never increased relative to beforeC
                lockReverted && afterC <= beforeC
            )
            ||
            (
                // Case B: lock succeeded -> c.balance is either same or decreased by 2 ether
                !lockReverted && (
                    afterC == midC || // no payout happened during settle (or settle reverted)
                    (beforeC >= 2 ether && afterC + 2 ether == beforeC) // paid out exactly 2 ether
                )
            )
        );
    }

    receive() external payable { }
}

