// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PredictTheBlockHashChallenge c;

    function setUp() public {
        vm.deal(address(this), 1 ether);
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
    }

    function _run(bytes32 guessHash, uint256 lockValue, bool callSettleBefore) internal {
        lockValue = bound(lockValue, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= lockValue);
        uint beforeC = address(c).balance;
        bool settleRevertedBefore;
        try c.settle() {
            settleRevertedBefore = false;
        } catch {
            settleRevertedBefore = true;
        }
        bool lockReverted;
        try c.lockInGuess{value: lockValue}(guessHash) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }
        uint midC = address(c).balance;
        bool settleRevertedAfter;
        try c.settle() {
            settleRevertedAfter = false;
        } catch {
            settleRevertedAfter = true;
        }
        uint afterC = address(c).balance;
        assertTrue((
                // Case A: lock failed -> c.balance never increased relative to beforeC
                lockReverted && afterC <= beforeC
            )
            ||
            (
                // Case B: lock succeeded -> c.balance is either same or decreased by 2 ether
                !lockReverted && (
                    afterC == midC || // no payout happened during settle (or settle reverted)
                    (beforeC >= 2 ether && afterC + 2 ether == beforeC) // paid out exactly 2 ether
                )
            ));
    }

    function testFuzz_run(bytes32 guessHash, uint256 lockValue, bool callSettleBefore) public {
        _run(guessHash, lockValue, callSettleBefore);
    }

    receive() external payable { }
}
